import pandas as pd
import numpy as np
import re

train = pd.read_csv('/work/b3_pvk_retention_train.csv')
pool = pd.read_csv('/work/b3_pvk_retention_pool.csv')

def score(r):
    s = 50.0
    notes = []
    c = r.composition
    etl = str(r.etl)
    htl = str(r.htl)
    bc = str(r.backcontact)
    arch = r.architecture
    dep = str(r.deposition)
    sub = str(r.substrate)

    # composition
    organic_A = any(x in c for x in ['MA','FA'])
    has_cs = 'Cs' in c
    has_br = 'Br' in c
    has_i = ('I' in c) and not (c.endswith('Br'))  # rough
    has_sn = 'Sn' in c
    has_2d = bool(re.search(r'PEA|BA|BDA|PEI|NMA|GU|PBA|ThMA|TFEA|BEA|NH4|HAPb|\(PEI\)|\(BDA\)|\(PBA\)|\(BEA\)|\(ThMA\)', c))

    if c in ['CsPbBr','CsPbTbBr','CsRbPbBr'] or (not organic_A and has_br and 'I' not in c.replace('Br','')):
        s += 32; notes.append('CsPbBr-family +32')
    elif not organic_A and has_br and 'I' in c:
        s += 22; notes.append('CsPbBrI +22')
    elif not organic_A:
        s += 10; notes.append('inorganic CsPbI-like +10')
    elif has_cs and has_br and 'FA' in c and 'MA' in c:
        s += 18; notes.append('CsFAMA mixed +18')
    elif has_cs and has_br:
        s += 15; notes.append('CsFA/CsMA Br +15')
    elif has_br and 'FA' in c:
        s += 12; notes.append('FAMA Br +12')
    elif has_cs:
        s += 8; notes.append('Cs-containing +8')
    elif 'FA' in c and 'MA' not in c.replace('FAMA','X'):
        s += 4; notes.append('FA-based +4')
    else:
        s += 0; notes.append('MAPbI-like 0')

    if has_sn:
        s -= 12; notes.append('Sn -12')
    if has_2d:
        s += 6; notes.append('2D +6')

    # back contact chemistry
    if 'Carbon' in bc:
        s += 18; notes.append('Carbon +18')
    elif 'Au' in bc and 'MoO' in bc:
        s += 10; notes.append('MoOx/Au +10')
    elif 'Au' in bc:
        s += 8; notes.append('Au +8')
    elif 'Cu' in bc and 'Au' not in bc:
        s += 4; notes.append('Cu +4')
    elif 'Ag' in bc and 'MoO' in bc:
        s -= 2; notes.append('MoO3/Ag -2')
    elif 'Ag' in bc:
        s += 0; notes.append('Ag 0')
    elif 'Al' in bc:
        s -= 10; notes.append('Al -10')
    else:
        s += 2

    # HTL
    inorg_htl = any(x in htl for x in ['NiO','NiMgLiO','CuPc','Cu2O','CuSCN','CuFeO','CZTS','MoO','VOx','rGO','Carbon','SnS','CuGaO','CsSn'])
    if htl == 'none':
        if 'Carbon' in bc:
            s += 12; notes.append('HTL-free carbon +12')
        else:
            s += 2; notes.append('HTL-free +2')
    elif 'PEDOT' in htl:
        s -= 12; notes.append('PEDOT -12')
    elif 'Spiro' in htl:
        s -= 6; notes.append('Spiro -6')
        if 'SWCNT' in htl or 'Carbon' in htl or 'WO3' in htl:
            s += 8; notes.append('Spiro+barrier +8')
    elif inorg_htl or 'NiMgLiO' in htl:
        s += 12; notes.append('inorganic HTL +12')
    elif 'PTAA' in htl:
        s += 4; notes.append('PTAA +4')
    elif 'P3HT' in htl:
        s += 3; notes.append('P3HT +3')
    else:
        s += 5; notes.append('other/dopant-free HTM +5')  # novel organics often dopant-free

    # ETL
    if 'ZrO2' in etl:
        s += 8; notes.append('ZrO2 spacer +8')
    if 'SnO2' in etl:
        s += 5; notes.append('SnO2 +5')
    elif 'ZnO' in etl:
        s -= 3; notes.append('ZnO -3')
    elif 'CdS' in etl:
        s += 2; notes.append('CdS +2')
    elif 'WOx' in etl or 'WO' in etl:
        s += 3; notes.append('WOx +3')
    if 'Graphene' in etl or 'Carbon-QD' in etl:
        s += 5; notes.append('C/graphene passivation +5')
    if 'TiO2-mp' in etl:
        s += 2; notes.append('mp scaffold +2')
    if 'PCBM' in etl or 'C60' in etl:
        s += 0

    # architecture
    if arch == 'nip':
        s += 3; notes.append('nip +3')
    else:
        # pin with inorganic HTL is good
        if inorg_htl or 'NiMgLiO' in htl:
            s += 4; notes.append('pin inorganic HTL +4')
        else:
            s += 0; notes.append('pin 0')

    # substrate
    if any(x in sub for x in ['PET','PEN','Textile']):
        s -= 8; notes.append('flexible -8')

    # deposition
    if 'Dropcasting' in dep or 'Drop-infiltration' in dep:
        s -= 4; notes.append('dropcast -4')

    return s, '; '.join(notes)

rows=[]
for r in pool.itertuples():
    s, n = score(r)
    rows.append((r.candidate_id, s, r.composition, r.architecture, r.etl, r.htl, r.backcontact, n))

df = pd.DataFrame(rows, columns=['id','score','comp','arch','etl','htl','bc','notes'])
df = df.sort_values('score', ascending=False)
print(df.head(25).to_string())
print('\n--- also score train to calibrate ---')
tr=[]
for r in train.itertuples():
    s, n = score(r)
    tr.append((s, r.target, r.composition, r.htl, r.backcontact))
tdf=pd.DataFrame(tr, columns=['score','y','c','h','b'])
print('corr', tdf.score.corr(tdf.y))
print(tdf.sort_values('score', ascending=False).head(15).to_string())
print('\nscore vs y bins')
tdf['bin']=pd.qcut(tdf.score, 5)
print(tdf.groupby('bin', observed=True)['y'].agg(['mean','median','count']))
